# FEASIBILITY MICRO-BENCHMARK ONLY (cost estimate; not an experiment, no schedule semantics).
import heapq, time, statistics

def dispatch_loop(p, ntasks_per_dev, dur=1.0):
    """Minimal device-dispatch loop: same machinery our real simulator needs
    (heap of device-free times, per-device FIFO ready queue, O(log p) push/pop)."""
    free = [0.0]*p
    heapq.heapify(free)
    t_end = 0.0
    for k in range(ntasks_per_dev):
        for d in range(p):
            t0 = heapq.heappop(free)
            t1 = t0 + dur * (1.0 + 0.01*(k % 7))
            heapq.heappush(free, t1)
            t_end = max(t_end, t1)
    return t_end

# largest configuration in the proposed grid: p=16, m=256(=16p), v=4 -> 2*m*p*v tasks
for (p, ntd, label) in [(16, 2*256*4, "p=16 v=4 m=256 (worst-case interleaved cell)"),
                        (16, 2*256,    "p=16 v=1 m=256 (non-interleaved cell)"),
                        (8,  2*128,    "p=8  v=1 m=128 (primary cell)")]:
    t0=time.perf_counter(); dispatch_loop(p, ntd); dt=time.perf_counter()-t0
    print("%-45s tasks=%7d  %.4f s  %.2f us/task" % (label, p*ntd, dt, dt/(p*ntd)*1e6))

# grid arithmetic
pset=[4,8,16,2]; methods=6
def mgrid(p):
    s=set([2*p-1])
    s|= {k*p for k in (2,3,4,6,8,12,16)}
    s|= set(range(2*p-1, 4*p+1))                       # dense at small m
    g=2*p-1
    while g < 16*p:                                     # ~45 geometric points
        g=int(g*1.09)+1; s.add(min(g,16*p))
    return sorted(x for x in s if 1<=x<=16*p)
tot_m=sum(len(mgrid(p)) for p in [4,8,16])
scen=9   # (beta=2,d=0)+(beta in 1.5,3)+(d in .1,.2 x4 seeds)+worst case
print("m-points per p:", {p:len(mgrid(p)) for p in [4,8,16]}, "total", tot_m)
print("non-interleaved cells = methods*sum(m)*scen =", methods*tot_m*scen)
tot_tasks=0
for p in [4,8,16]:
    for m in mgrid(p):
        for meth in range(methods):
            v = 4 if meth in (1,3) else 1
            tot_tasks += 2*m*p*v
print("total task-events over grid x1 scenario: %.2e" % tot_tasks)
