# MACHINERY COST + VALIDATION-CONTROL FEASIBILITY CHECK ONLY.
# Purpose: (1) measure realistic per-event cost of a dependency-aware event loop
#          (2) show the design's "formula validation" control is implementable in stdlib.
# This is NOT an experiment: no curve is produced, no method comparison, one control cell only.
import heapq, time

def sim_1f1b(p, m, beta=2.0, iters=1):
    f, b = 1.0, beta
    # device model: p devices; tasks F[i][j], B[i][j]
    readyF = [[0.0]*m for _ in range(p)]
    readyB = [[0.0]*m for _ in range(p)]
    dev_free = [0.0]*p
    doneB_last = 0.0
    for it in range(iters):
        base = it * 0.0
        live = 0
        order = []
        for i in range(p):
            warm = min(p-1-i, m)
            js = list(range(m))
            # 1F1B: warmup forwards, then alternate F,B
            seq = [('F', j) for j in js[:warm]]
            k = warm; nb = 0
            while k < m or nb < m:
                if k < m: seq.append(('F', js[k])); k += 1
                if nb < m: seq.append(('B', js[nb])); nb += 1
            order.append(seq)
        ptr = [0]*p
        pend = [dict() for _ in range(p)]   # j -> completion time
        t_done_dev = 0.0
        active = True
        while active:
            active = False
            progressed = True
            while progressed:
                progressed = False
                for i in range(p):
                    if ptr[i] >= len(order[i]): continue
                    kind, j = order[i][ptr[i]]
                    # data dependency
                    if kind == 'F':
                        dep = 0.0 if i == 0 else pend[i-1].get('F%d'%j)
                    else:
                        dep = pend[i].get('F%d'%j) if True else None
                        if dep is None: continue
                        if i < p-1:
                            d2 = pend[i+1].get('B%d'%j)
                            if d2 is None: continue
                            dep = max(dep, d2)
                    if dep is None: continue
                    st = max(dev_free[i], dep)
                    dur = f if kind == 'F' else b
                    dev_free[i] = st + dur
                    pend[i]['%s%d' % (kind, j)] = dev_free[i]
                    ptr[i] += 1
                    active = True
                    progressed = True
                else:
                    progressed = False
        t_done_dev = max(dev_free)
        ideal = m*(f+b)
        bubble_single = 1 - ideal/t_done_dev
        ref = (p-1)*beta/(m*(1+beta)+(p-1)*beta)
    return t_done_dev, bubble_single, ref

p, m = 8, 64
t0 = time.perf_counter(); mk, bub, ref = sim_1f1b(p, m); dt = time.perf_counter()-t0
ev = 2*p*m
print("control cell p=8 m=64: events=%d time=%.4fs  %.2f us/event" % (ev, dt, dt/ev*1e6))
print("validation-control check: sim bubble=%.6f  analytic ref=%.6f  absdiff=%.2e" % (bub, ref, abs(bub-ref)))
