# for 1F1B (merged B), split-B 1F1B, and interleaved 1F1B-I. No verdict, no ZB, no curves.
import math

def run(S, p_of, m, durF, durB, durB2=0.0, warm=None):
    """S stages (virtual if interleaved), device(stage)->dev. 1F1B op order."""
    dev = [p_of(k) for k in range(S)]
    ndev = max(dev)+1
    free = [0.0]*ndev
    Fc, B1c, B2c = {}, {}, {}
    ops = []
    for k in range(S):
        w = (S-1-k) if warm is None else warm
        w = min(w, m)
        seq = [('F',j) for j in range(w)]
        kf, kb = w, 0
        while kf < m or kb < m:
            if kf < m: seq.append(('F',kf)); kf += 1
            if kb < m: seq.append(('B',kb)); kb += 1
        ops.append(seq)
    ptr=[0]*S; pend=True
    while pend:
        pend=False
        for k in range(S):
            while ptr[k] < len(ops[k]):
                kind,j = ops[k][ptr[k]]
                if kind=='F':
                    dep = 0.0 if k==0 else Fc.get((k-1,j))
                    if dep is None: break
                    st=max(free[k],dep); free[k]=st+durF; Fc[(k,j)]=free[k]
                else:
                    d0 = Fc.get((k,j));  d1 = 0.0 if k==S-1 else B1c.get((k+1,j))
                    if d0 is None or (k<S-1 and d1 is None): break
                    st=max(free[k],d0,d1); free[k]=st+durB; B1c[(k,j)]=free[k]
                    if durB2>0:
                        free[k]+=durB2; B2c[(k,j)]=free[k]
                ptr[k]+=1; pend=True
    return max(free)

print("--- merged B (w=1+beta), candidate C=(p-1)*(1+beta)  => c=C/w=p-1")
for p in (2,3,4,8):
    for beta in (1,2,3):
        for m in (p, 2*p, 4*p):
            mk = run(p, lambda k:k, m, 1.0, float(beta))
            w = 1+beta; C = mk-m*w; print("  p=%-2d b=%s m=%-3d makespan=%5.2f C=%5.2f  c=C/w=%5.3f (p-1=%d)"%(p,beta,m,mk,C,C/w,p-1))

print("--- split B1/B2 (w=1+b1+b2, drain=b1), candidate C=(p-1)*(1+b1)")
for p in (2,3,4,8):
    for (b1,b2) in ((1.0,1.0),(1.0,2.0)):
        for m in (p, 4*p):
