            print("  p=%-2d b1=%g b2=%g m=%-3d makespan=%6.2f C=%5.2f c=C/w=%5.3f | (p-1)(1+b1)/w=%5.3f"%(p,b1,b2,m,mk,C,C/w,(p-1)*(1+b1)/w))

print("--- interleaved 1F1B-I: S=p*v virtual stages, dev=k mod p, vstage work/v")
for p in (4,8):
