# DERIVATION CHECK (design-time, NOT the experiment): which closed form gives c_ref?
# makespan = m*w + C + o(1);  c := C/w = slope of (1/m, 1/throughput_norm).
def run(S, dev_of, m, durF, durB1, durB2=0.0, durOPT=0.0):
    ndev = max(dev_of(k) for k in range(S))+1
    free=[0.0]*ndev; Fc={}; B1c={}
    ops=[]
    for k in range(S):
        w=min(S-1-k,m); seq=[('F',j) for j in range(w)]
        kf, kb = w, 0
        while kf < m or kb < m:
            if kf < m: seq.append(('F',kf)); kf+=1
            if kb < m: seq.append(('B',kb)); kb+=1
        ops.append(seq)
    ptr=[0]*S; go=True
    while go:
        go=False
        for k in range(S):
            d=dev_of(k)
            while ptr[k]<len(ops[k]):
                kind,j=ops[k][ptr[k]]
                if kind=='F':
                    dep = 0.0 if k==0 else Fc.get((k-1,j))
                    if dep is None: break
                    st=max(free[d],dep); free[d]=st+durF; Fc[(k,j)]=free[d]
                else:
                    d0=Fc.get((k,j)); d1=0.0 if k==S-1 else B1c.get((k+1,j))
                    if d0 is None or (k<S-1 and d1 is None): break
                    st=max(free[d],d0,d1); free[d]=st+durB1
                    if durB2>0: free[d]+=durB2
                    if durOPT>0: free[d]+=durOPT
                    B1c[(k,j)]=free[d]
                ptr[k]+=1; go=True
    return max(free)

print("== 1F1B-I (v virtual stages/dev, chain length p*v, per-vstage work w/v) ==")
print("   split invocations: F=1/v, B1=b1/v, B2=b2/v ; w=1+b1+b2")
for p in (4,8):
  for v in (2,4):
    for (b1,b2) in ((1.0,1.0),):
      w=1+b1+b2
      for k in (1,2,4,8):
        m=k*p*v
        mk=run(p*v, lambda x:x%p, m, 1.0/v, b1/v, b2/v)
        C=mk-m*w; c=C/w
        print("  p=%d v=%d m=%-4d C=%7.3f c=%7.4f | (p-1)(1+b1)/(v*w)=%7.4f | (p-1/v)(1+b1)/w=%7.4f"%(
            p,v,m,C,c,(p-1)*(1+b1)/(v*w),(p-1.0/v)*(1+b1)/w))
print("== merged-B 1F1B cross-check: c should be (p-1)*(f+b1')/w, b1'=b (drain=B) ==")
for p in (4,8):
  for beta in (1,2,3):
    mk=run(p, lambda x:x, 8*p, 1.0, float(beta)); w=1+beta; print("  p=%d b=%s c=%.4f | (p-1)(1+b)/w=%.4f | p-1=%d"%(p,beta,(mk-8*p*w)/w,(p-1)*(1+beta)/w,p-1))
print("== OPT tail effect on c (split, p=8, b1=b2=1, opt=o): drain= B1 only, OPT is local tail ==")
for o in (0.0,0.05,0.2,1.0):
    w=1+1+1+o; mk=run(8, lambda x:x, 64, 1.0,1.0,1.0,o); print("  opt=%.2f w=%.2f C=%.3f c=%.4f | (p-1)(1+b1)/w=%.4f"%(o,w,mk-64*w,(mk-64*w)/w,7*2/w))
EOF
