def sim(p, m, b1, b2, K, opt=0.0):
    w = 1+b1+b2+opt
    free=[0.0]*p; Fc={}; B1c={}
    ops=[]
    for i in range(p):
        seq=[]
        for it in range(K):
            wm=min(p-1-i,m); seq += [('F',it,j) for j in range(wm)]
            kf,kb=wm,0
            while kf<m or kb<m:
                if kf<m: seq.append(('F',it,kf)); kf+=1
                if kb<m: seq.append(('B',it,kb)); kb+=1
        ops.append(seq)
    ptr=[0]*p; go=True; Fk=lambda it,j:(i_,it,j)
    while go:
        go=False
        for i in range(p):
