                    st=max(free[i],d0,d1); free[i]=st+b1
                    if b2>0: free[i]+=b2
                    if opt>0: free[i]+=opt
                    B1c[(i,it,j)]=free[i]
                ptr[i]+=1; go=True
    return max(free), w

