# It hinges on whether B2 (local weight-grad) is (wrongly) put on the cross-stage dependency chain.
def sim(p,m,b1,b2,opt=0.0,couple_b2_in_chain=True):
    w=1+b1+b2+opt
    free=[0.0]*p; Fc={}; B1c={}
    ops=[]
    for i in range(p):
        wm=min(p-1-i,m); seq=[('F',j) for j in range(wm)]
        kf,kb=wm,0
        while kf<m or kb<m:
            if kf<m: seq.append(('F',kf)); kf+=1
            if kb<m: seq.append(('B',kb)); kb+=1
        ops.append(seq)
    ptr=[0]*p; go=True
    while go:
        go=False
        for i in range(p):
            while ptr[i]<len(ops[i]):
                kind,j=ops[i][ptr[i]]
                if kind=='F':
                    dep=0.0 if i==0 else Fc.get((i-1,j))
                    if dep is None: break
                    st=max(free[i],dep); free[i]=st+1.0; Fc[(i,j)]=free[i]
                else:
                    d0=Fc.get((i,j)); d1=0.0 if i==p-1 else B1c.get((i+1,j))
                    if d0 is None or (i<p-1 and d1 is None): break
                    st=max(free[i],d0,d1)
                    free[i]=st+b1
                    tail = (free[i] if couple_b2_in_chain else st+b1)
                    free[i]+= b2+opt
                    # cross-stage signal is the input-grad, available right after B1
                    B1c[(i,j)] = tail if couple_b2_in_chain else st+b1
                ptr[i]+=1; go=True
    return max(free), w
print("coupled(B2 on the return chain) vs decoupled(B1 signal only): p=8, f=1, b1=b2=1, opt=0")
for m in (8,16,64,256):
    Ta,w=sim(8,m,1,1,True);  Tb,_=sim(8,m,1,1,False)
    print("  m=%-4d w=%.2f  T_coup=%7.2f W0=%6.2f c=%.3f | T_dec=%7.2f W0=%6.2f c=%.3f"%(
        m,w,Ta,Ta-m*w,(Ta-m*w)/w,Tb,Tb-m*w,(Tb-m*w)/w))
print("  candidates: (p-1)(f+b)=%d  (p-1)(f+b1)=%d   c: p-1=%.1f  (p-1)(f+b1)/w=%.3f"%(7*2,7*2,7,7*2/3))
print("merged-B equivalent check (b2=0,b1=beta): W0 should be (p-1)(f+beta) => c=p-1")
for beta in (1.0,2.0,3.0):
    T,w=sim(8,64,beta,0.0,True); print("  beta=%.1f w=%.2f W0=%.2f c=%.4f (p-1=%d)"%(beta,w,T-64*w,(T-64*w)/w,7))
