# Correct Megatron-style interleaving: flatten (chunk c, microbatch j) -> M=v*m virtual
# microbatches; device d runs virtual stage k=c*p+d; 1F1B order on the flattened list.
def sim(p, v, m, b1, b2=0.0, opt=0.0, coupled=True):
    cw = (1+b1+b2+opt)/v          # per-virtual-microbatch device work
    cF, cB = 1.0/v, b1/v
    M = v*m
    free=[0.0]*p; Fc={}; B1c={}
    # virtual stage k = c*p + d ; chain order k=0..p*v-1
    ops=[]
    for k in range(p*v):
        wm=min(p*v-1-k, M)
        seq=[('F',j) for j in range(wm)]
        kf,kb=wm,0
        while kf<M or kb<M:
            if kf<M: seq.append(('F',kf)); kf+=1
            if kb<M: seq.append(('B',kb)); kb+=1
        ops.append(seq)
    ptr=[0]*(p*v); dev=lambda k: k%p; go=True
    while go:
        go=False
        for k in range(p*v):
            d=dev(k)
            while ptr[k]<len(ops[k]):
                kind,j=ops[k][ptr[k]]
                if kind=='F':
                    dep=0.0 if k==0 else Fc.get((k-1,j))
                    if dep is None: break
                    st=max(free[d],dep); free[d]=st+cF; Fc[(k,j)]=free[d]
