                    d0=Fc.get((k,j)); d1=0.0 if k==p*v-1 else B1c.get((k+1,j))
                    if d0 is None or (k<p*v-1 and d1 is None): break
                    st=max(free[d],d0,d1); free[d]=st+cB
                    tail=free[d]
                    free[d]+= (b2+opt)/v
                    B1c[(k,j)]= tail if coupled else st+cB
                ptr[k]+=1; go=True
    return max(free), 1+b1+b2+opt

k = lambda b1,b2,opt: (1+b1)/(1+b1+b2+opt)
print("nominal split f=1,b1=1,b2=1,opt=0 -> kappa=2/3 ; merged b2=0,b1=beta -> kappa=1")
for (b1,b2,opt,lab) in [(1.0,1.0,0.0,"split k=2/3"),(2.0,0.0,0.0,"merged b=2 k=1")]:
