# DESIGN-TIME check: does stage skew (delta>0) inflate the fitted additive c,
# i.e. must the numeric c_ref acceptance be restricted to delta=0 scenarios?
import random
def sim(p,m,b1,b2,skew,opt=0.0):
    fF=[1.0*s for s in skew]; fB1=[b1*s for s in skew]; fB2=[b2*s for s in skew]
    w0=1+b1+b2
    free=[0.0]*p; Fc={}; B1c={}
    ops=[]
    for i in range(p):
        wm=min(p-1-i,m); seq=[('F',j) for j in range(wm)]
        kf,kb=wm,0
        while kf<m or kb<m:
            if kf<m: seq.append(('F',kf)); kf+=1
            if kb<m: seq.append(('B',kb)); kb+=1
        ops.append(seq)
    ptr=[0]*p; go=True
    while go:
        go=False
        for i in range(p):
            while ptr[i]<len(ops[i]):
                kind,j=ops[i][ptr[i]]
                if kind=='F':
                    dep=0.0 if i==0 else Fc.get((i-1,j))
                    if dep is None: break
                    st=max(free[i],dep); free[i]=st+fF[i]; Fc[(i,j)]=free[i]
                else:
                    d0=Fc.get((i,j)); d1=0.0 if i==p-1 else B1c.get((i+1,j))
                    if d0 is None or (i<p-1 and d1 is None): break
                    st=max(free[i],d0,d1); free[i]=st+fB1[i]; t=free[i]; free[i]+=fB2[i]
                    B1c[(i,j)]=t
                ptr[i]+=1; go=True
    # reference work under skew: slowest device work per microbatch (weighted mean per stage is irrelevant;
    # per-device work varies -> use mean per-stage work as w for normalization)
    return max(free)
p=8; w=3.0; cref=(p-1)*2/3
for delta in (0.0,0.1,0.2):
    for seed in (1,2):
        r=random.Random(seed); skew=[1.0+delta*r.uniform(-1,1) for _ in range(p)]
        ms=max(skew)
        W0s=[]
        for m in (128,256):
            T=sim(p,m,1.0,1.0,skew); W0s.append(T-m*(sum(skew)/p)*w/1.0*1.0)  # normalize by mean stage work
        # simple scale-free diagnostic: throughput at m and growth of (T - m*wbar)
        print("  delta=%.1f seed=%d mean_skew=%.3f max_skew=%.3f  W0(128)=%8.2f W0(256)=%8.2f  (const? => c well-defined)"%(
            delta,seed,sum(skew)/p,ms,W0s[0],W0s[1]))
print("  nominal c_ref (split, p=8, b1=1) = %.4f ; c under merged drain would be p-1 = %d"%(cref,p-1))
